    private IEnumerable<Character> FilteredCharacters
    {
        get
        {
            // Decide what houses should be allowed
            LinkedList<string> houses = new LinkedList<string>();
            if (gryffindor)
            {
                houses.AddLast("Gryffindor");
            }
            if (slytherin) 
            {
                houses.AddLast("Slytherin");
            }
            if (hufflepuff) 
            {
                houses.AddLast("Hufflepuff");
            }
            if (ravenclaw) 
            {
                houses.AddLast("Ravenclaw");
            }
            if (houseless)
            {
                houses.AddLast("");
            }
            //create list of allowed houses



            if (string.IsNullOrWhiteSpace(CharacterSearchText))
            {
                if (houses.Count == 0)
                {
                    return CharacterList.Where(character =>
                           ((character.HogwartsStudent == true) || (character.HogwartsStudent == student)) && ((character.HogwartsStaff == true) || (character.HogwartsStaff == staff)));
                 }
                else
                {
                    return CharacterList.Where(character =>
                           ((character.HogwartsStudent == true) || (character.HogwartsStudent == student)) && ((character.HogwartsStaff == true) || (character.HogwartsStaff == staff)) && (houses.Find(character.House) != null)); //check student, check staff, check if in list of allowed houses
                }
            }
            else
            {
                if (houses.Count == 0)
                {
                   return CharacterList.Where(character =>
                         (character.Name?.Contains(CharacterSearchText, StringComparison.OrdinalIgnoreCase) ?? false)
                         && ((character.HogwartsStudent == true) || (character.HogwartsStudent == student)) && ((character.HogwartsStaff == true) || (character.HogwartsStaff == staff)));
                }
                else
                {
                    return CharacterList.Where(character =>
                           ((character.Name?.Contains(CharacterSearchText, StringComparison.OrdinalIgnoreCase) ?? false) && (character.HogwartsStudent == true) || (character.HogwartsStudent == student)) && ((character.HogwartsStaff == true) || (character.HogwartsStaff == staff)) && (houses.Find(character.House) != null)); //check student, check staff, check if in list of allowed houses
                
                }
            }
        }
    }

